+/** Theoretical (from imported sales) vs actual (consume movements) use per item between two days, inclusive. */
+export function varianceReport(store, from, to) {
+  const round = (n) => Math.round(n * 1000) / 1000;
+  const lines = new Map();
+  const line = (itemId) => {
+    if (!lines.has(itemId)) lines.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    return lines.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const u of s.uses) line(u.itemId).theoretical += u.qty;
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to || !batchItem.has(m.batchId)) continue;
+    line(batchItem.get(m.batchId)).actual += m.qty;
+  }
+  return [...lines.values()]
+    .map((l) => ({ ...l, theoretical: round(l.theoretical), actual: round(l.actual) }))
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .map((l) => ({ ...l, name: store.data.items.find((i) => i.id === l.itemId)?.name ?? "", difference: round(l.actual - l.theoretical) }))
+    .sort((a, b) => a.itemId - b.itemId);
+}
